const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const API=new URLSearchParams(location.search).get('api')||'http://127.0.0.1:8000/api/v1';
let token=localStorage.getItem('studymate_token')||'', profile=null, suggestions=[], matches=[], activeFilter='all', selectedProfile=null;
const types={exam:'Ôn thi',project:'Làm project',new_skill:'Học skill mới',competition:'Hackathon/Cuộc thi',daily:'Học chung hàng ngày'};
const levelLabels={beginner:'Mới bắt đầu',basic:'Cơ bản',intermediate:'Trung bình',advanced:'Nâng cao'};
const schedule=['T2-sáng','T2-chiều','T2-tối','T3-sáng','T3-chiều','T3-tối','T4-sáng','T4-chiều','T4-tối','T5-sáng','T5-chiều','T5-tối','T6-sáng','T6-chiều','T6-tối','T7-sáng','T7-chiều','T7-tối','CN-sáng','CN-chiều','CN-tối'];
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const initial=name=>(name||'B').trim().charAt(0).toUpperCase();

async function api(path,options={}){const headers={...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers};if(token)headers.Authorization=`Bearer ${token}`;const response=await fetch(API+path,{...options,headers});if(response.status===401){logout();throw new Error('Phiên đăng nhập đã hết hạn.')}const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'Không thể kết nối máy chủ.');return data}
function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),2800)}
function showApp(){ $('#authScreen').classList.add('hidden');$('#appShell').classList.remove('hidden') }
function showAuth(){ $('#appShell').classList.add('hidden');$('#authScreen').classList.remove('hidden') }
function logout(){token='';localStorage.removeItem('studymate_token');showAuth()}

$$('[data-auth]').forEach(button=>button.onclick=()=>{$$('[data-auth]').forEach(x=>x.classList.toggle('active',x===button));$$('.auth-form').forEach(x=>x.classList.remove('active'));$('#'+button.dataset.auth+'Form').classList.add('active')});
$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;$('#loginError').textContent='';try{const data=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});token=data.access_token;localStorage.setItem('studymate_token',token);showApp();await loadAll()}catch(err){$('#loginError').textContent=err.message}finally{button.disabled=false}};
$('#registerForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;$('#registerError').textContent='';try{const data=await api('/auth/register',{method:'POST',body:JSON.stringify({email:$('#registerEmail').value,password:$('#registerPassword').value,display_name:$('#registerName').value,university:$('#registerUniversity').value,study_year:$('#registerYear').value,age:19,intent:'project'})});token=data.access_token;localStorage.setItem('studymate_token',token);showApp();await loadAll();go('profile');notify('Tài khoản đã sẵn sàng — hoàn thiện hồ sơ nhé!')}catch(err){$('#registerError').textContent=err.message}finally{button.disabled=false}};
$('#logoutButton').onclick=logout;

function go(page){$$('.page').forEach(x=>x.classList.toggle('active',x.id===page+'Page'));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('.sidebar').classList.remove('open');scrollTo({top:0,behavior:'smooth'});if(page==='connections')loadMatches();}
$$('[data-page]').forEach(button=>button.onclick=()=>go(button.dataset.page));$('#menuButton').onclick=()=>$('.sidebar').classList.toggle('open');

function completion(p){const fields=['university','major','study_year','match_description','skill_level','interaction_mode','commitment_level','contact'];let filled=fields.filter(k=>p[k]).length;filled+=(p.skills||[]).length?1:0;filled+=(p.available_times||[]).length?1:0;filled+=(p.match_types||[]).length?1:0;return Math.round(filled/11*100)}
function updateIdentity(){const name=profile.display_name||'Bạn', meta=[profile.study_year,profile.university].filter(Boolean).join(' · ')||'Sinh viên';$('#sideName').textContent=name;$('#sideMeta').textContent=meta;$('#welcomeName').textContent=name;$('#sideAvatar').textContent=initial(name);$('#topAvatar').textContent=initial(name);$('#profileAvatar').textContent=initial(name);$('#profileCardName').textContent=name;$('#profileCardMeta').textContent=meta;const done=completion(profile);$('#profileStat').textContent=done+'%';$('#completePercent').textContent=done+'%';$('#completeBar').style.width=done+'%'}
function csv(value){return (value||[]).join(', ')}
function parseCsv(value){return value.split(',').map(x=>x.trim()).filter(Boolean)}
function fillProfile(){const p=profile;$('#pName').value=p.display_name||'';$('#pUniversity').value=p.university||'';$('#pYear').value=p.study_year||'Năm 1';$('#pMajor').value=p.major||'';$('#pLocation').value=p.location||p.city||'';$('#pDescription').value=p.match_description||'';$('#pSkills').value=csv(p.skills);$('#pLevel').value=p.skill_level||'beginner';$('#pUrgency').value=p.urgency||'soon';$('#pMode').value=p.interaction_mode||'both';$('#pCommitment').value=p.commitment_level||'medium';$('#pContact').value=p.contact||'';$('#pPersonality').value=csv(p.personality_tags);$$('#matchTypeChoices button').forEach(b=>b.classList.toggle('selected',(p.match_types||[]).includes(b.dataset.value)));$$('#scheduleChoices button').forEach(b=>b.classList.toggle('selected',(p.available_times||[]).includes(b.dataset.value)));updateIdentity()}

$('#scheduleChoices').innerHTML=schedule.map(s=>`<button type="button" data-value="${s}">${s.replace('-',' · ')}</button>`).join('');
$('#matchTypeChoices').onclick=e=>{const b=e.target.closest('button');if(b)b.classList.toggle('selected')};$('#scheduleChoices').onclick=e=>{const b=e.target.closest('button');if(b)b.classList.toggle('selected')};
function profilePayload(){const matchTypes=$$('#matchTypeChoices .selected').map(x=>x.dataset.value);return{display_name:$('#pName').value.trim(),age:profile.age||19,city:$('#pLocation').value.trim(),occupation:`Sinh viên ${$('#pMajor').value.trim()}`,bio:profile.bio||'',intent:matchTypes[0]||'project',interests:profile.interests||[],available_times:$$('#scheduleChoices .selected').map(x=>x.dataset.value),university:$('#pUniversity').value.trim(),major:$('#pMajor').value.trim(),study_year:$('#pYear').value,skills:parseCsv($('#pSkills').value),skill_level:$('#pLevel').value,current_courses:profile.current_courses||[],learning_goals:profile.learning_goals||'',tools_used:profile.tools_used||[],match_types:matchTypes,match_description:$('#pDescription').value.trim(),team_size_needed:profile.team_size_needed||'1',urgency:$('#pUrgency').value,interaction_mode:$('#pMode').value,location:$('#pLocation').value.trim(),communication_style:profile.communication_style||'text',commitment_level:$('#pCommitment').value,personality_tags:parseCsv($('#pPersonality').value),strengths:profile.strengths||[],weaknesses:profile.weaknesses||[],notes:profile.notes||'',deal_breakers:profile.deal_breakers||'',contact:$('#pContact').value.trim()}}
async function saveProfile(e){e?.preventDefault();const payload=profilePayload();if(!payload.display_name||!payload.university||!payload.match_types.length||!payload.match_description){notify('Hãy điền tên, trường, loại và mô tả nhu cầu.');return}try{profile=await api('/profiles/me',{method:'PUT',body:JSON.stringify(payload)});fillProfile();await loadSuggestions(true);notify('Đã lưu hồ sơ và cập nhật gợi ý!');go('discover')}catch(err){notify(err.message)}}
$('#profileForm').onsubmit=saveProfile;$('#saveProfileTop').onclick=saveProfile;

function card(p){const title=p.anonymous_name||`Bạn học #${p.user_id}`, tags=[...(p.skills||[]),...(p.current_courses||[])].slice(0,4);return `<article class="match-card" data-type="${esc((p.match_types||[]).join(' '))}"><div class="match-top"><span class="match-avatar">${initial(p.name)}</span><div class="match-name"><b>${esc(title)}</b><small>${esc([p.study_year,p.university,p.major].filter(Boolean).join(' · '))}</small></div><span class="score" style="--score:${p.score}%"><b>${p.score}%</b></span></div><p class="need">${esc(p.match_description||p.bio||'Đang tìm một người bạn học phù hợp.')}</p><div class="tags">${tags.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="reason-box"><b>✦ Vì sao phù hợp?</b><br>${esc((p.reasons||[]).slice(0,2).join(' · '))}</div><div class="match-actions"><button class="button outline" data-preview="${p.user_id}">Xem hồ sơ</button><button class="button primary" data-connect="${p.user_id}">Kết nối</button></div></article>`}
function bindCards(container){container.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>preview(Number(b.dataset.preview)));container.querySelectorAll('[data-connect]').forEach(b=>b.onclick=()=>connect(Number(b.dataset.connect),b))}
function renderSuggestions(){const filtered=activeFilter==='all'?suggestions:suggestions.filter(p=>(p.match_types||[]).includes(activeFilter));$('#suggestionStat').textContent=suggestions.length;$('#allMatches').innerHTML=filtered.length?filtered.map(card).join(''):'<div class="empty">Chưa có gợi ý trong nhóm này. Hãy thử bộ lọc khác.</div>';$('#homeMatches').innerHTML=suggestions.length?suggestions.slice(0,3).map(card).join(''):'<div class="empty">Hoàn thiện hồ sơ để nhận gợi ý phù hợp.</div>';bindCards($('#allMatches'));bindCards($('#homeMatches'))}
async function loadSuggestions(refresh=false){try{const data=await api('/discover'+(refresh?'?refresh=true':''));suggestions=data.items||[];renderSuggestions()}catch(err){$('#allMatches').innerHTML=`<div class="empty">${esc(err.message)}</div>`}}
$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.toggle('active',x===b));activeFilter=b.dataset.filter;renderSuggestions()});$('#refreshButton').onclick=()=>loadSuggestions(true);

function preview(id){selectedProfile=suggestions.find(x=>x.user_id===id);if(!selectedProfile)return;const p=selectedProfile;$('#previewContent').innerHTML=`<div class="preview-hero"><span class="match-avatar">${initial(p.name)}</span><h2>${esc(p.anonymous_name)}</h2><p class="muted">${esc([p.study_year,p.university,p.major].filter(Boolean).join(' · '))}</p></div><div class="compat"><div><b>Compatibility</b><b>${p.score}% phù hợp</b></div><ul>${(p.reasons||[]).map(x=>`<li>✓ ${esc(x)}</li>`).join('')}</ul></div><div class="preview-section"><h3>Nhu cầu học tập</h3><p>${esc(p.match_description||p.bio)}</p></div><div class="preview-section"><h3>Kỹ năng & môn học</h3><div class="tags">${[...(p.skills||[]),...(p.current_courses||[])].map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></div><div class="preview-section"><h3>Phong cách</h3><div class="tags">${(p.personality_tags||[]).map(x=>`<span class="tag">#${esc(x)}</span>`).join('')}</div></div><div class="modal-actions"><button class="button outline" data-close>Bỏ qua</button><button class="button primary" id="modalConnect">🤝 Muốn kết nối</button></div>`;openModal('profileModal');$('#modalConnect').onclick=()=>connect(p.user_id,$('#modalConnect'));$('#profileModal [data-close]').onclick=closeModals}
async function connect(id,button){button.disabled=true;try{const result=await api('/interactions',{method:'POST',body:JSON.stringify({target_user_id:id,action:'like'})});suggestions=suggestions.filter(x=>x.user_id!==id);renderSuggestions();closeModals();if(result.is_match){await loadMatches();await showStarter(result.match_id)}else notify('Đã gửi lời mời. Thông tin liên hệ chỉ mở khi cả hai đồng ý.')}catch(err){notify(err.message);button.disabled=false}}

async function loadMatches(){try{const data=await api('/matches');matches=data.items||[];$('#connectionStat').textContent=matches.length;$('#matchBadge').textContent=matches.length;$('#connectionList').innerHTML=matches.length?matches.map(m=>`<article class="connection"><span class="match-avatar">${initial(m.name)}</span><div class="meta"><b>${esc(m.name)}</b><small>${esc([m.study_year,m.university,m.major].filter(Boolean).join(' · '))}</small><div class="tags">${(m.skills||[]).slice(0,4).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></div><button class="button soft" data-kit="${m.match_id}">✦ Bộ phá băng</button></article>`).join(''):'<div class="empty"><b>Chưa có kết nối.</b><br>Gửi lời mời cho người phù hợp ở trang Tìm bạn học.</div>';$$('[data-kit]').forEach(b=>b.onclick=()=>showStarter(Number(b.dataset.kit)))}catch(err){notify(err.message)}}
async function showStarter(matchId){try{const k=await api(`/matches/${matchId}/starter-kit`);$('#successContent').innerHTML=`<div class="success-burst">🎉</div><span class="eyebrow">MATCH THÀNH CÔNG</span><h2>Bạn và ${esc(k.partner.name)} đã kết nối!</h2><p>AI đã chuẩn bị sẵn một khởi đầu thật tự nhiên.</p><div class="intro-box"><b>👋 Thẻ giới thiệu</b><br>${esc(k.introduction)}</div><h3 style="text-align:left;font-size:13px">🧊 Gợi ý phá băng <small style="color:#888;font-weight:400">· bấm để sao chép</small></h3><div class="ice-list">${k.ice_breakers.map((x,i)=>`<div class="ice-item" data-copy="${esc(x)}"><b>${i+1}.</b> ${esc(x)}</div>`).join('')}</div><div class="activity-box"><b>🎯 Hoạt động đầu tiên</b><br>${esc(k.activity)}</div><div class="contact-box"><b>Liên hệ:</b> ${esc(k.partner.contact||'Đối phương chưa cập nhật')}</div><div class="modal-actions"><button class="button primary" data-close>Đã hiểu, bắt đầu thôi →</button></div>`;openModal('successModal');$$('[data-copy]').forEach(x=>x.onclick=async()=>{await navigator.clipboard?.writeText(x.dataset.copy);notify('Đã sao chép câu mở đầu!')});$('#successModal [data-close]').onclick=closeModals}catch(err){notify(err.message)}}
function openModal(id){$('#'+id).classList.remove('hidden')}function closeModals(){$$('.modal').forEach(x=>x.classList.add('hidden'))}$$('.modal').forEach(m=>m.onclick=e=>{if(e.target===m)closeModals()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModals()});

async function loadAll(){try{profile=await api('/profiles/me');fillProfile();await Promise.all([loadSuggestions(),loadMatches()]);showApp()}catch(err){notify(err.message)}}
(async()=>{if(token){showApp();await loadAll()}else showAuth()})();
